<script setup>
import {computed,onBeforeUnmount,reactive,watch} from 'vue';
import {Puzzle,RefreshCw} from 'lucide-vue-next';
import {api} from '../api.js';
import {botTime} from '../bot-state.js';
import {createDshPlugins,dshPluginsReason,dshRuntimeEntries} from '../dsh-plugins.js';
const props=defineProps({workspace:{type:String,required:true},actorId:{type:String,required:true},employee:{type:Object,required:true},active:Boolean,externalBlocked:Boolean});
const emit=defineEmits(['state']);
const ui=createDshPlugins({api,wrap:reactive}),s=ui.state;
const subject=computed(()=>({workspace:props.workspace,actorId:props.actorId,employeeId:props.employee.id,deviceId:props.employee.target_device_id??null,profile:props.employee.runtime_profile??null,runtime:props.employee.runtime}));
const entries=computed(()=>dshRuntimeEntries(s.value?.runtime));
const busy=computed(()=>s.loading||s.submitting||Boolean(s.value?.pending));
const notice=computed(()=>s.notice||(s.value?.reasonCode?dshPluginsReason(s.value.reasonCode):''));
const namespaces=computed(()=>s.value?.configuration?.namespaces||[]);
function fields(namespace){const schema=namespace.schema,refs=schema?.refs||{},root=refs[schema?.uid];return Object.entries(root?.dict||{}).map(([name,id])=>({name,type:refs[id]?.type||'原生类型',constraints:Object.entries(refs[id]?.meta||{}).filter(([key])=>['min','max','step','pattern','required','length'].includes(key)).map(([key,value])=>key+'='+String(value)).join(' · ')}));}
watch(()=>[...Object.values(subject.value),props.active],()=>{void ui.select(subject.value,{active:props.active});},{immediate:true});
watch(()=>[s.loading,s.submitting,s.request,s.value?.pending],()=>emit('state',{busy:s.loading||s.submitting,pending:Boolean(s.request||s.value?.pending)}),{immediate:true});
onBeforeUnmount(()=>ui.dispose());
</script>

<template>
  <section class="dsh-plugins-panel" aria-label="DSH 原生插件" :aria-busy="busy">
    <header class="plugins-heading"><div><p class="plugins-eyebrow"><Puzzle :size="14" aria-hidden="true"/>DSH 原生系统</p><h3>插件组合</h3><p>同步绑定 Bot 的原生目录。保存只影响下次启动，不会启动或重启 Bot。</p></div><div class="plugins-actions"><button type="button" class="plugins-button" :disabled="s.loading||s.submitting" @click="ui.load()">回读状态</button><button type="button" class="plugins-button" :disabled="externalBlocked||busy||Boolean(s.request)" @click="!externalBlocked&&ui.refresh()"><RefreshCw :size="14" aria-hidden="true"/>同步原生目录</button></div></header>
    <dl class="plugins-context"><div><dt>绑定 Bot</dt><dd>{{s.value?.subject.profile||employee.runtime_profile||'尚未绑定'}}</dd></div><div><dt>来源</dt><dd>{{s.value?.snapshot?.source||'尚未观察'}}</dd></div><div><dt>读取时间</dt><dd>{{s.value?.snapshot?.checkedAt?botTime(s.value.snapshot.checkedAt):'尚无记录'}}</dd></div></dl>
    <p v-if="s.error" class="plugins-notice error" role="alert">{{s.error}}</p><p v-if="notice" class="plugins-notice" role="status">{{notice}}</p>
    <p v-if="externalBlocked" class="plugins-notice">原生管理还有未核实的原请求，插件组合暂不可提交；可继续回读状态。</p>
    <div v-if="s.request" class="plugins-pending"><p>原请求 {{s.request.actionId||'回执待确认'}} · {{s.request.operation==='apply'?'保存插件组合':'只读目录同步'}}</p><button v-if="s.unknown" type="button" class="plugins-button" :disabled="externalBlocked||busy" @click="!externalBlocked&&ui.retry()">按原请求重试</button></div>
    <p v-if="s.loading&&!s.value" class="plugins-empty" role="status">正在读取原生插件快照…</p>
    <template v-if="s.value">
      <p v-if="s.value.stale" class="plugins-notice">当前快照已过期，仅供参考；同步成功后才能编辑。</p>
      <div class="plugins-section-heading"><h4>已保存组合</h4><span>{{ui.dirty()?'有本地草稿':'与读取记录一致'}}</span></div>
      <div v-if="s.value.plugins.length" class="plugins-catalog"><label v-for="plugin in s.value.plugins" :key="plugin.id" class="plugins-item"><input type="checkbox" :aria-label="'启用插件：'+plugin.name" :checked="s.draft.includes(plugin.id)" :disabled="externalBlocked||!ui.editable()||plugin.required" @change="!externalBlocked&&ui.toggle(plugin.id,$event.target.checked)"/><span><strong>{{plugin.name}}<small v-if="plugin.required">必需</small></strong><span v-if="plugin.description" class="plugins-description">{{plugin.description}}</span><code>{{plugin.id}}</code><small class="plugins-saved">已保存 · {{plugin.enabled?'启用':'未启用'}}</small></span></label></div>
      <p v-else class="plugins-empty">尚无可编辑的原生目录。请检查运行电脑与客户端支持后同步。</p>
      <footer class="plugins-save"><p>插件组合与实际加载分开核实。{{s.value.restartRequired===true?'原生报告：下次启动生效。':'保存后的生效时间以原生回执为准。'}}</p><button type="button" class="plugins-button primary" :disabled="externalBlocked||!ui.editable()||!ui.dirty()" @click="!externalBlocked&&ui.save()">{{s.submitting&&s.request?.operation==='apply'?'提交中…':'保存插件组合'}}</button></footer>
      <details class="plugins-evidence"><summary>运行时加载观察</summary><p>仅展示 DSH 返回的 bundle、Loader 条目与预设阶段；原生启用标记不等于已加载。</p><p v-if="s.value.runtime.status!=='observed'" class="plugins-empty">尚无运行时加载证据。Bot 未运行或原生 RPC 不可读时，不能判断插件已加载。</p><template v-else><p>{{s.value.runtime.bundles?.length||0}} 个运行时 bundle · {{entries.length}} 个 Loader / 预设条目</p><details><summary>运行时 bundle 清单</summary><ul><li v-for="bundle in s.value.runtime.bundles||[]" :key="bundle.name"><code>{{bundle.name}}</code> · 原生启用标记 {{String(bundle.enabled)}}</li></ul></details><ul class="plugins-runtime"><li v-for="(entry,index) in entries" :key="entry.scope+':'+entry.entryId+':'+index"><strong>{{entry.moduleName||entry.entryId}}</strong><span>{{entry.scope}} · 原生启用标记 {{String(entry.enabled)}} · 实际阶段 {{entry.phase}}</span></li></ul></template></details>
      <details class="plugins-evidence"><summary>原生字段元数据</summary><p>插件参数、账号连接及权限请在原生 DSH 端编辑。本页只显示字段元数据，不读取或写入配置值。</p><p v-if="!namespaces.length" class="plugins-empty">尚无可读的字段元数据。</p><details v-for="namespace in namespaces" :key="namespace.ns"><summary>{{namespace.ns}}</summary><dl class="plugins-fields"><div v-for="field in fields(namespace)" :key="field.name"><dt>{{field.name}}</dt><dd>{{field.type}}{{field.constraints?' · '+field.constraints:''}}</dd></div></dl></details></details>
    </template>
  </section>
</template>

<style scoped>
.dsh-plugins-panel{min-width:0;color:var(--bot-ink,#403747);font-size:12px}.plugins-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.plugins-heading h3{margin:6px 0 8px;font-size:18px}.plugins-heading p,.plugins-save p,.plugins-evidence p{margin:0;line-height:1.8;color:var(--bot-muted,#81738c)}.plugins-eyebrow{display:flex;align-items:center;gap:6px;font-size:11px}.plugins-actions{display:flex;gap:8px;flex-wrap:wrap;flex-shrink:0}.plugins-button{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-height:32px;padding:6px 10px;border:0;border-radius:7px;background:#f2eff7;color:#665879;font:inherit;cursor:pointer;white-space:nowrap}.plugins-button:hover{background:#eae4f3}.plugins-button.primary{background:#7655c7;color:#fff}.plugins-button.primary:hover{background:#6746b4}.plugins-button:disabled{opacity:.48;cursor:default}.plugins-button:focus-visible,.plugins-item input:focus-visible,.plugins-evidence summary:focus-visible{outline:2px solid #a88af0;outline-offset:3px}.plugins-context{display:flex;flex-wrap:wrap;gap:12px 24px;margin:20px 0;padding:12px 0;border-block:1px solid #eee9f2}.plugins-context>div{display:grid;gap:4px;min-width:0}.plugins-context dt{font-size:11px;color:#968ba0}.plugins-context dd{margin:0;overflow-wrap:anywhere}.plugins-notice{padding:10px 12px;border-radius:7px;background:#f5f2fa;color:#79658c;line-height:1.8}.plugins-notice.error{background:#fff3f3;color:#9a5866}.plugins-pending{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;overflow-wrap:anywhere;color:#84768e}.plugins-section-heading{display:flex;justify-content:space-between;gap:10px;align-items:center;margin:20px 0 8px}.plugins-section-heading h4{margin:0;font-size:13px}.plugins-section-heading>span{color:#978ba0;font-size:11px}.plugins-catalog{border-block:1px solid #eee9f2}.plugins-item{display:flex;align-items:flex-start;gap:10px;padding:14px 0;border-bottom:1px solid #f0edf5;cursor:pointer}.plugins-item:last-child{border-bottom:0}.plugins-item input{flex:none;width:16px;height:16px;margin:3px 0 0;accent-color:#7655c7}.plugins-item>span{display:grid;gap:5px;min-width:0}.plugins-item strong{font-size:13px;overflow-wrap:anywhere}.plugins-item strong small{font-weight:400;font-size:10px;margin-left:8px;color:#8c7b99;background:#f1edf7;border-radius:4px;padding:2px 5px}.plugins-description{color:#82758d;line-height:1.7}.plugins-item code,.plugins-evidence code{font-size:10px;color:#9689a2;overflow-wrap:anywhere}.plugins-saved{color:#9a8da6;font-size:10px}.plugins-save{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:16px 0 24px}.plugins-save p{max-width:430px;font-size:11px}.plugins-empty{padding:12px 0;color:#91849d;line-height:1.8}.plugins-evidence{padding:14px 0;border-top:1px solid #eee9f2}.plugins-evidence summary{cursor:pointer;color:#71627e;line-height:1.8}.plugins-evidence p{margin:10px 0;font-size:11px}.plugins-evidence details{margin:10px 0}.plugins-evidence ul{list-style:none;padding:0;font-size:11px}.plugins-evidence li{padding:7px 0;overflow-wrap:anywhere}.plugins-runtime{max-height:280px;overflow:auto}.plugins-runtime li{display:grid;gap:4px}.plugins-runtime span{font-size:10px;color:#9689a2}.plugins-fields{display:grid;gap:9px}.plugins-fields>div{display:grid;gap:4px;overflow-wrap:anywhere}.plugins-fields dd{margin:0;font-size:11px;color:#9689a2}@media(max-width:760px){.plugins-heading{display:block}.plugins-actions{margin-top:12px}.plugins-save{align-items:flex-start;flex-direction:column}.plugins-context{gap:12px 20px}}@media(pointer:coarse){.plugins-button{min-height:36px}}
</style>
